// FontButton — Gtk.FontButton
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles fontbutton with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface FontButtonProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.FontButton */
  modal?: boolean

  /** utf8, from Gtk.FontButton */
  title?: string

  /** gboolean, from Gtk.FontButton */
  useFont?: boolean

  /** gboolean, from Gtk.FontButton */
  useSize?: boolean
}

export function FontButton({ className, children, title }: FontButtonProps) {
  return (
    <div className={cn(className)}>
      {title}
      {children}
    </div>
  )
}
